// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 _val) internal {
        vm.assume(true);
        uint beforeBalance = address(c).balance;
        bool reverted;
        try c.SetMinSum(_val) { reverted = false; } catch { reverted = true; }
        assertTrue(!reverted && c.MinSum() == _val && address(c).balance == beforeBalance);
    }

    function testFuzz_run(uint256 _val) public {
        _run(_val);
    }

    receive() external payable {}
}
